wManager.wManagerSetting.CurrentSetting.UseMount = false;
System.Func<string, int> cnt = (cond) => Lua.LuaDoString<int>("local n=0 for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,c,_,id=GetQuestLogTitle(i) if not h and id==12372 then for j=1,GetNumQuestLeaderBoards(i) do local t,ty,f=GetQuestLogLeaderBoard(j,i) " + cond + " end end end return n");
System.Func<int> kills = () => cnt("if not f and not string.find(t,'Dragonshrine') then n=n+1 end");
System.Func<int> shrine = () => cnt("if not f and string.find(t,'Dragonshrine') then n=n+1 end");
var end = System.DateTime.Now.AddMinutes(20);
int tries = 0;
int pi = 0;
int probe = 0;
var patrol = new Vector3[] { new Vector3(3331f, 487f, 0f), new Vector3(3250f, 650f, 0f), new Vector3(3400f, 250f, 0f), new Vector3(3150f, 486f, 0f) };
var probes = new float[] { 0f, 50f, -50f, 100f, -100f };
while (robotManager.Products.Products.IsStarted && System.DateTime.Now < end && tries < 6 && Quest.HasQuest(12372) && (kills() > 0 || shrine() > 0))
{
    tries++;
    if (!ObjectManager.Me.InTransport)
    {
        bool found = false; float bd = 99999f; Vector3 dp = new Vector3();
        foreach (var u in ObjectManager.GetObjectWoWUnit())
        {
            if (u.Entry == 27629 && !u.IsDead && u.GetDistance < bd) { bd = u.GetDistance; dp = u.Position; found = true; }
        }
        if (!found)
        {
            wManager.Wow.Bot.Tasks.GoToTask.ToPosition(new Vector3(3543.63f, 304.604f, 116.9709f));
            System.Threading.Thread.Sleep(1500);
            continue;
        }
        wManager.Wow.Bot.Tasks.GoToTask.ToPositionAndIntecractWithNpc(dp, 27629);
        System.Threading.Thread.Sleep(1500);
        Lua.LuaDoString("if GossipFrame and GossipFrame:IsVisible() then GossipTitleButton1:Click() end");
        System.Threading.Thread.Sleep(3500);
        if (!ObjectManager.Me.InTransport) continue;
    }
    var rideEnd = System.DateTime.Now.AddMinutes(10);
    var lastHeal = System.DateTime.Now;
    var lastProbe = System.DateTime.Now;
    while (robotManager.Products.Products.IsStarted && System.DateTime.Now < rideEnd && ObjectManager.Me.InTransport && Quest.HasQuest(12372) && (kills() > 0 || shrine() > 0))
    {
        var mp = ObjectManager.Me.Position;
        bool haveT = false; float td = 99999f; Vector3 tp = new Vector3(); ulong tg = 0;
        bool killPhase = kills() > 0;
        foreach (var u in ObjectManager.GetObjectWoWUnit())
        {
            if (killPhase ? (!u.IsDead && (u.Entry == 27608 || u.Entry == 27682)) : (u.Entry == 27698))
            {
                if (u.GetDistance < td) { td = u.GetDistance; tp = u.Position; tg = u.Guid; haveT = true; }
            }
        }
        if (!haveT && !killPhase)
        {
            if ((System.DateTime.Now - lastProbe).TotalSeconds > 6) { probe++; lastProbe = System.DateTime.Now; }
            float off = probes[probe % probes.Length];
            tp = new Vector3(3144f + off, 486f + off, mp.Z);
            td = mp.DistanceTo(tp);
            haveT = true;
        }
        if (haveT)
        {
            if (tg != 0) ObjectManager.Me.Target = tg;
            if (td > 14f) MovementManager.MoveTo(tp.X, tp.Y, tp.Z);
            if (td <= 30f)
            {
                MovementManager.Face(tp);
                Lua.LuaDoString("VehicleMenuBarActionButton1:Click()");
            }
        }
        else
        {
            var p = patrol[pi % patrol.Length];
            if (mp.DistanceTo(new Vector3(p.X, p.Y, mp.Z)) < 40f) pi++;
            MovementManager.MoveTo(p.X, p.Y, mp.Z);
        }
        if ((System.DateTime.Now - lastHeal).TotalSeconds > 8)
        {
            lastHeal = System.DateTime.Now;
            int hp = Lua.LuaDoString<int>("return math.floor(UnitHealth('vehicle')*100/math.max(UnitHealthMax('vehicle'),1))");
            if (hp < 60) { Lua.LuaDoString("VehicleMenuBarActionButton3:Click()"); System.Threading.Thread.Sleep(500); Lua.LuaDoString("VehicleMenuBarActionButton2:Click()"); }
        }
        System.Threading.Thread.Sleep(600);
    }
    if (ObjectManager.Me.InTransport && kills() == 0 && shrine() == 0)
    {
        Lua.LuaDoString("VehicleExit()");
        System.Threading.Thread.Sleep(2500);
    }
}
if (ObjectManager.Me.InTransport && (kills() == 0 && shrine() == 0 || !Quest.HasQuest(12372)))
{
    Lua.LuaDoString("VehicleExit()");
    System.Threading.Thread.Sleep(2500);
}

